// D is DISCRETE: the slider snaps to the integer on release. The := directive is
// read ONLY from the scriptCode, so it must be written here (the JSON key
// "discreteConstants" does not survive a save from the app).
D := int(1,20);

// N sullo slider D, intero fra 1 e 20.
float N = clamp(floor(D + 0.5), 1.0, 20.0);

// The mesh sections are static text: there are always 20. The copies beyond N
// collapse into a point (factor 0) instead of being drawn: a
// degenerate mesh produces no visible area.
float live = step(mesh, N - 0.5);

// Geometry of the Villarceau circle. B < A so that the square root is real.
float bb = clamp(B, 0.0, A - 0.001);
float cc = sqrt(A * A - bb * bb) / A;
float ss = bb / A;

// Tube of radius C around the core, in the Frenet frame of the circle (plane
// curve: constant binormal, the frame does not twist).
float R = A - C * cos(v);

float px = (R * cc * cos(u) - C * ss * sin(v)) * live;
float py = (bb + R * sin(u)) * live;
float pz = (R * ss * cos(u) + C * cc * sin(v)) * live;

float ang = 6.28318531 * mesh / N;
float ca = cos(ang);
float sa = sin(ang);

// The body becomes the body of vec4 getRawPosition(...): the return MUST be a
// vec4, with the fourth component (4D coordinate) at 0 for a surface in R^3.
return vec4(
    px * ca - py * sa,
    px * sa + py * ca,
    pz,
    0.0
);
